void UAlsAnimationInstance::RefreshFeetOnGameThread()
{
	check(IsInGameThread())

	const auto* Mesh{GetSkelMeshComponent()};
	const auto PelvisTransform{Mesh->GetSocketTransform(UAlsConstants::PelvisBoneName(), RTS_Component)};

	if (bPendingUpdate)
	{
		FeetState.bValid = false;
		FeetState.bBecameValid = false;
	}
	else if (!FeetState.bValid)
	{
		// USkinnedMeshComponent::GetSocketTransform() can return an invalid transform in some cases, so we need to check this.
		// Ideally, we should use USkinnedMeshComponent.::bHasValidBoneTransform here instead, but it can't be accessed.
		// TODO Wait for https://github.com/EpicGames/UnrealEngine/pull/14322 to be merged into the engine.

		if (PelvisTransform.EqualsNoScale(FTransform::Identity))
		{
			return;
		}

		FeetState.bValid = true;
		FeetState.bBecameValid = true;
	}
	else
	{
		FeetState.bBecameValid = false;
	}

	FeetState.PelvisRotation = FQuat4f{PelvisTransform.GetRotation()};

	const auto FootLeftTargetTransform{
		Mesh->GetSocketTransform(Settings->General.bUseFootIkBones
			                         ? UAlsConstants::FootLeftIkBoneName()
			                         : UAlsConstants::FootLeftVirtualBoneName())
	};

	FeetState.Left.TargetLocationWorldSpace = FootLeftTargetTransform.GetLocation();
	FeetState.Left.TargetRotationWorldSpace = FootLeftTargetTransform.GetRotation();

	const auto FootRightTargetTransform{
		Mesh->GetSocketTransform(Settings->General.bUseFootIkBones
			                         ? UAlsConstants::FootRightIkBoneName()
			                         : UAlsConstants::FootRightVirtualBoneName())
	};

FTransform USkinnedMeshComponent::GetSocketTransform(FName InSocketName, ERelativeTransformSpace TransformSpace) const
{
	//QUICK_SCOPE_CYCLE_COUNTER(USkinnedMeshComponent_GetSocketTransform);

	FTransform OutSocketTransform = GetComponentTransform();

	if (InSocketName != NAME_None)
	{
		int32 SocketBoneIndex;
		FTransform SocketLocalTransform;
		USkeletalMeshSocket const* const Socket = GetSocketInfoByName(InSocketName, SocketLocalTransform, SocketBoneIndex);
		// apply the socket transform first if we find a matching socket
		if (Socket)
		{
			if (TransformSpace == RTS_ParentBoneSpace)
			{
				//we are done just return now
				return SocketLocalTransform;
			}

			if (SocketBoneIndex != INDEX_NONE)
			{
				FTransform BoneTransform = GetBoneTransform(SocketBoneIndex);
				OutSocketTransform = SocketLocalTransform * BoneTransform;
			}
		}
		else
		{
			int32 BoneIndex = GetBoneIndex(InSocketName);
			if (BoneIndex != INDEX_NONE)
			{
				OutSocketTransform = GetBoneTransform(BoneIndex);

				if (TransformSpace == RTS_ParentBoneSpace)
				{
					FName ParentBone = GetParentBone(InSocketName);
					int32 ParentIndex = GetBoneIndex(ParentBone);
					if (ParentIndex != INDEX_NONE)
					{
						return OutSocketTransform.GetRelativeTransform(GetBoneTransform(ParentIndex));
					}
					return OutSocketTransform.GetRelativeTransform(GetComponentTransform());

